def remove_invalid_parentheses(s):
    if valid(s):
        return [s]
    answers = set()
    for index, character in enumerate(s):
        if character in "()":
            candidate = s[:index] + s[index + 1:]
            if valid(candidate):
                answers.add(candidate)
    return list(answers)

def valid(text):
    balance = 0
    for character in text:
        balance += character == "(" 
        balance -= character == ")"
        if balance < 0:
            return False
    return balance == 0
